function S({registerIndicator:p,sourceValues:d,nulls:y}){p({id:"oa-gauss",name:"Gaussian Filter (GAUSS)",category:"Filters",placement:"onchart",inputs:[{key:"sigma",type:"number",label:"Sigma",default:1,min:.1,max:10,step:.1,tooltip:"Standard deviation of the Gaussian kernel. The kernel spans 2 * ceil(3 * sigma) + 1 bars, so a larger sigma smooths harder and lags more."},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"gauss",type:"line",title:"Gaussian",style:{color:"#ffeb3b",lineWidth:2}}],calc(l,f){const o=Math.min(10,Math.max(.1,Number(f.sigma)||1)),r=d(l,f.source??"close"),s=2*Math.ceil(3*o)+1,b=Math.floor(s/2),n=new Array(s);let c=0;for(let e=0;e<s;e++){const t=e-b,a=Math.exp(-(t*t)/(2*o*o));n[e]=a,c+=a}if(c!==0){const e=1/c;for(let t=0;t<s;t++)n[t]*=e}const u=new Array(l.length).fill(NaN);for(let e=0;e<l.length;e++){const t=Math.min(e+1,s);let a=0,m=0;for(let i=0;i<t;i++){const g=r[e-i];Number.isFinite(g)&&(a+=g*n[i],m+=n[i])}const h=m!==0?a/m:NaN;Number.isFinite(h)?u[e]=h:Number.isFinite(r[e])&&(u[e]=r[e])}return{gauss:y(u)}}})}export{S as default};
